declare(strict_types=1); require_once __DIR__.'/../shared/response.php'; require_once __DIR__.'/../shared/request.php'; methodOnly('GET'); safeApi(function():void{$db=apiDatabase();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$slug=isset($_GET['slug'])?trim((string)$_GET['slug']):'';$where=$id?'id=:id':($slug?'slug=:slug':'1=1');$s=$db->prepare("SELECT * FROM blogs WHERE $where ORDER BY created_at DESC");$s->execute($id?[':id'=>$id]:($slug?[':slug'=>$slug]:[]));$d=($id||$slug)?$s->fetch():$s->fetchAll();if(($id||$slug)&&!$d)jsonResponse(false,'Blog not found.',null,[],404);jsonResponse(true,'Blogs loaded.',$d);});
